static const int B = 5;               // try 1..5 consecutive edge removals
static const int spurinterval = 3;    // sample every spurinterval nodes across path
static const int psblts_cap = 800;    // candidateidate psblts cap
static const int itr_nodes = 4; // after picking a candidateidate, we may generate local spurs

static inline uint64_t edge_key(int u, int v)
{
  return ((uint64_t)(uint32_t)u << 32) | (uint64_t)(uint32_t)v;
}

// hash function fully generated by chatgpt!

static inline uint64_t hash_path(const std::vector<int> &path)
{
  const uint64_t FNV_offset = 1469598103934665603ULL;
  const uint64_t FNV_prime = 1099511628211ULL;
  uint64_t h = FNV_offset;
  for (int x : path)
  {
    h ^= (uint64_t)(x % 10);
    h *= FNV_prime;
  }
  return h;
}

static inline std::unordered_set<uint64_t> path_edges(const std::vector<int> &path)
{
  std::unordered_set<uint64_t> s;
  if (path.size() < 2)
    return s;
  s.reserve(path.size() - 1);
  for (size_t i = 0; i + 1 < path.size(); i++)
    s.insert(edge_key(path[i], path[i + 1]));
  return s;
}

static inline double overlap_perc_set(const std::unordered_set<uint64_t> &A, const std::unordered_set<uint64_t> &B)
{
  if (A.empty() || B.empty())
    return 0.0;
  // find perc of the smaller path that is overslapping
  const std::unordered_set<uint64_t> *small = &A, *big = &B;
  if (A.size() > B.size())
  {
    small = &B;
    big = &A;
  }
  int common = 0;
  // iterating over smol so i iterate less
  for (auto &e : *small)
    if (big->count(e))
      common++;
  return 100.0 * (double)common / (double)small->size();
}

std::vector<std::vector<int>> Graph::k_short_heuristic(int src, int target, int k, int overlap_threshold)
{
  std::vector<std::vector<int>> ans;

  double shotty = 0.0;
  std::vector<int> base = shortest_path(src, target, shotty);
  if (base.empty())
    return ans;

  struct candidate
{
    std::vector<int> p;
    double len;
    double penalty;

    bool operator<(const candidate &other) const
    {
        if (penalty != other.penalty)
            return penalty < other.penalty;
        return len < other.len;
    }
};


  std::vector<candidate> selected;
  selected.reserve(k);
  selected.push_back({base, shotty});
  std::unordered_set<uint64_t> bpaths = path_edges(base);

